 "content": "from collections import Counter


def transform(grid):
    """Decode colors at the corners of rectangular cells in a repeated field."""
    h, w = len(grid), len(grid[0]) if grid else 0
    if not h or not w:
        return []

    # Repeated-grid separators are nearly uniform horizontal rails. A stricter
    # row cutoff prevents the broad interior color from being mistaken for them.
    rail_candidates = []
    for r, row in enumerate(grid):
        color, count = Counter(row).most_common(1)[0]
        if count / w >= 0.85:
            rail_candidates.append((r, color))

    if rail_candidates:
        base = Counter(color for _, color in rail_candidates).most_common(1)[0][0]
        rows = [r for r in range(h) if sum(v == base for v in grid[r]) / w >= 0.85]
        cols = [c for c in range(w) if sum(grid[r][c] == base for r in range(h)) / h >= 0.70]
        if len(rows) >= 2 and len(cols) >= 2:
            marked = [(r, c) for r in rows for c in cols if grid[r][c] != base]
            if marked:
                rmin, rmax = min(r for r, _ in marked), max(r for r, _ in marked)
                cmin, cmax = min(c for _, c in marked), max(c for _, c in marked)
                rows = [r for r in rows if rmin <= r <= rmax]
                cols = [c for c in cols if cmin <= c <= cmax]
                nonbase = [v for row in grid for v in row if v != base]
                fill = Counter(nonbase).most_common(1)[0][0] if nonbase else base
                result = []
                for i in range(len(rows) - 1):
                    out_row = []
                    for j in range(len(cols) - 1):
                        corners = (grid[rows[i]][cols[j]], grid[rows[i]][cols[j + 1]],
                                   grid[rows[i + 1]][cols[j]], grid[rows[i + 1]][cols[j + 1]])
                        color = corners[0]
                        out_row.append(color if color != base and all(v == color for v in corners) else fill)
                    result.append(out_row)
                if result:
                    return result

    # Sparse corner-marker examples may have no continuous separator rails.
    # A color occurring exactly at all four corners of a rectangle represents
    # that rectangle as a single output cell.
    positions = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            positions.setdefault(color, []).append((r, c))
    for color, pts in positions.items():
        if len(pts) != 4:
            continue
        rs = sorted({r for r, _ in pts})
        cs = sorted({c for _, c in pts})
        if len(rs) == len(cs) == 2 and set(pts) == {(rs[0], cs[0]), (rs[0], cs[1]), (rs[1], cs[0]), (rs[1], cs[1])}:
            return [[color]]

    return [row[:] for row in grid]


